"use client"

import { useState, useRef, useEffect } from "react"
import { createPortal } from "react-dom"
import Link from "next/link"

interface CompareActionsMenuProps {
  compareId: string
  onDelete: () => void
}

export function CompareActionsMenu({ compareId, onDelete }: CompareActionsMenuProps) {
  const [open, setOpen] = useState(false)
  const [position, setPosition] = useState({ top: 0, left: 0 })

  const triggerRef = useRef<HTMLButtonElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // Calculate dropdown position
  useEffect(() => {
    if (open && triggerRef.current) {
      const rect = triggerRef.current.getBoundingClientRect()
      const dropdownWidth = 192

      setPosition({
        top: rect.bottom + 4,
        left: rect.right - dropdownWidth,
      })
    }
  }, [open])

  // Click outside handler
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const target = event.target as Node

      if (open && triggerRef.current && dropdownRef.current) {
        if (!triggerRef.current.contains(target) && !dropdownRef.current.contains(target)) {
          setOpen(false)
        }
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [open])

  return (
    <>
      <button
        ref={triggerRef}
        className="p-1.5 text-text-muted hover:text-text-primary rounded hover:bg-[#222222] transition-colors cursor-pointer"
        onClick={(e) => {
          e.stopPropagation()
          setOpen(!open)
        }}
      >
        <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
          <path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z" />
        </svg>
      </button>

      {/* Dropdown menu */}
      {open &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={dropdownRef}
            className="fixed z-[9999] w-48 bg-[#0b0b0e] border border-[#333333] rounded overflow-hidden"
            style={{
              top: position.top,
              left: position.left,
              boxShadow: "0 4px 16px rgba(34, 34, 34, 0.5)",
            }}
          >
            <div className="py-1">
              <Link
                href={`/compare/${encodeURIComponent(compareId)}`}
                className="w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer text-text-secondary hover:bg-[#222222] hover:text-text-primary"
                onClick={() => setOpen(false)}
              >
                view details
              </Link>

              <div className="border-t border-[#333333] my-1" />

              <button
                className="w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer text-status-error hover:bg-[#222222]"
                onClick={() => {
                  onDelete()
                  setOpen(false)
                }}
              >
                delete
              </button>
            </div>
          </div>,
          document.body
        )}
    </>
  )
}

"use client"

import { useState, useRef, useEffect } from "react"
import { createPortal } from "react-dom"
import Link from "next/link"
import { cn } from "@/lib/utils"

interface RunActionsMenuProps {
  runId: string
  provider: string
  benchmark: string
  status: string
  onAddToLeaderboard: (data: { version?: string; notes?: string }) => Promise<void>
  onDelete: () => void
  onTerminate?: () => void
  onContinue?: () => void
}

export function RunActionsMenu({
  runId,
  provider,
  benchmark,
  status,
  onAddToLeaderboard,
  onDelete,
  onTerminate,
  onContinue,
}: RunActionsMenuProps) {
  const [open, setOpen] = useState(false)
  const [showLeaderboardPopover, setShowLeaderboardPopover] = useState(false)
  const [position, setPosition] = useState({ top: 0, left: 0 })
  const [popoverPosition, setPopoverPosition] = useState({ top: 0, left: 0 })

  const triggerRef = useRef<HTMLButtonElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)
  const popoverRef = useRef<HTMLDivElement>(null)

  const isCompleted = status === "completed"
  const isRunning = status === "running" || status === "pending"
  const isStopping = status === "stopping"
  const isFailed = status === "failed"
  const isPartial = status === "partial"
  const canContinue = isFailed || isPartial

  // Calculate dropdown position
  useEffect(() => {
    if (open && triggerRef.current) {
      const rect = triggerRef.current.getBoundingClientRect()
      const dropdownWidth = 192

      setPosition({
        top: rect.bottom + 4,
        left: rect.right - dropdownWidth,
      })
    }
  }, [open])

  // Calculate popover position
  useEffect(() => {
    if (showLeaderboardPopover && triggerRef.current) {
      const rect = triggerRef.current.getBoundingClientRect()
      const popoverWidth = 320

      setPopoverPosition({
        top: rect.bottom + 4,
        left: Math.max(16, rect.right - popoverWidth),
      })
    }
  }, [showLeaderboardPopover])

  // Click outside handler
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const target = event.target as Node

      // Handle dropdown
      if (open && triggerRef.current && dropdownRef.current) {
        if (!triggerRef.current.contains(target) && !dropdownRef.current.contains(target)) {
          setOpen(false)
        }
      }

      // Handle popover
      if (showLeaderboardPopover && popoverRef.current) {
        if (!popoverRef.current.contains(target)) {
          setShowLeaderboardPopover(false)
        }
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [open, showLeaderboardPopover])

  const handleOpenLeaderboard = () => {
    setOpen(false)
    setShowLeaderboardPopover(true)
  }

  return (
    <>
      <button
        ref={triggerRef}
        className="p-1.5 text-text-muted hover:text-text-primary rounded hover:bg-[#222222] transition-colors cursor-pointer"
        onClick={(e) => {
          e.stopPropagation()
          setOpen(!open)
        }}
      >
        <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
          <path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z" />
        </svg>
      </button>

      {/* Dropdown menu */}
      {open &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={dropdownRef}
            className="fixed z-[9999] w-48 bg-[#0b0b0e] border border-[#333333] rounded overflow-hidden"
            style={{
              top: position.top,
              left: position.left,
              boxShadow: "0 4px 16px rgba(34, 34, 34, 0.5)",
            }}
          >
            <div className="py-1">
              <Link
                href={`/runs/${encodeURIComponent(runId)}`}
                className="w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer text-text-secondary hover:bg-[#222222] hover:text-text-primary"
                onClick={() => setOpen(false)}
              >
                view details
              </Link>

              <button
                className={cn(
                  "w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer",
                  !isCompleted
                    ? "text-text-muted cursor-not-allowed"
                    : "text-text-secondary hover:bg-[#222222] hover:text-text-primary"
                )}
                disabled={!isCompleted}
                onClick={handleOpenLeaderboard}
              >
                add to leaderboard
              </button>

              {canContinue && (
                <>
                  <div className="border-t border-[#333333] my-1" />
                  <button
                    className="w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer text-accent hover:bg-[#222222]"
                    onClick={() => {
                      onContinue?.()
                      setOpen(false)
                    }}
                  >
                    continue
                  </button>
                </>
              )}

              <div className="border-t border-[#333333] my-1" />

              {isRunning || isStopping ? (
                <button
                  className={cn(
                    "w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer",
                    isStopping
                      ? "text-text-muted cursor-not-allowed"
                      : "text-status-error hover:bg-[#222222]"
                  )}
                  disabled={isStopping}
                  onClick={() => {
                    onTerminate?.()
                    setOpen(false)
                  }}
                >
                  {isStopping ? "stopping..." : "terminate"}
                </button>
              ) : (
                <button
                  className="w-full px-3 py-2 text-sm text-left transition-colors flex items-center gap-2 cursor-pointer text-status-error hover:bg-[#222222]"
                  onClick={() => {
                    onDelete()
                    setOpen(false)
                  }}
                >
                  delete
                </button>
              )}
            </div>
          </div>,
          document.body
        )}

      {/* Leaderboard popover */}
      {showLeaderboardPopover &&
        typeof document !== "undefined" &&
        createPortal(
          <LeaderboardPopover
            ref={popoverRef}
            position={popoverPosition}
            provider={provider}
            benchmark={benchmark}
            onSubmit={async (data) => {
              await onAddToLeaderboard(data)
              setShowLeaderboardPopover(false)
            }}
            onClose={() => setShowLeaderboardPopover(false)}
          />,
          document.body
        )}
    </>
  )
}

// Separate popover component for adding to leaderboard
import { forwardRef } from "react"

interface LeaderboardPopoverProps {
  position: { top: number; left: number }
  provider: string
  benchmark: string
  onSubmit: (data: { version?: string; notes?: string }) => Promise<void>
  onClose: () => void
}

const LeaderboardPopover = forwardRef<HTMLDivElement, LeaderboardPopoverProps>(
  ({ position, provider, benchmark, onSubmit, onClose }, ref) => {
    const [editingVersion, setEditingVersion] = useState(false)
    const [version, setVersion] = useState("")
    const [notes, setNotes] = useState("")
    const [isSubmitting, setIsSubmitting] = useState(false)

    const versionInputRef = useRef<HTMLInputElement>(null)

    useEffect(() => {
      if (editingVersion && versionInputRef.current) {
        versionInputRef.current.focus()
      }
    }, [editingVersion])

    const handleSubmit = async () => {
      try {
        setIsSubmitting(true)
        await onSubmit({
          version: version.trim() || undefined,
          notes: notes.trim() || undefined,
        })
      } catch (e) {
        alert(e instanceof Error ? e.message : "failed to add to leaderboard")
      } finally {
        setIsSubmitting(false)
      }
    }

    return (
      <div
        ref={ref}
        className="fixed z-[9999] w-80 bg-[#0b0b0e] border border-[#333333] rounded overflow-hidden"
        style={{
          top: position.top,
          left: position.left,
          boxShadow: "0 4px 16px rgba(34, 34, 34, 0.5)",
        }}
      >
        {/* Header */}
        <div className="px-4 py-3 border-b border-[#333333] flex items-center justify-between">
          <span className="text-sm text-text-primary">add to leaderboard</span>
          <button
            className="text-text-muted hover:text-text-primary transition-colors cursor-pointer"
            onClick={onClose}
          >
            <svg
              className="w-4 h-4"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-4 space-y-4">
          {/* Provider / Benchmark */}
          <div className="text-xs text-text-muted">
            <span className="lowercase">{provider}</span>
            <span className="mx-1">/</span>
            <span className="lowercase">{benchmark}</span>
          </div>

          {/* Version */}
          <div className="space-y-1.5">
            <label className="text-xs text-text-muted">version</label>
            {!editingVersion ? (
              <button
                className="flex items-center gap-2 text-sm text-text-primary hover:text-accent transition-colors cursor-pointer"
                onClick={() => setEditingVersion(true)}
              >
                <span className="font-medium lowercase">{version || "baseline"}</span>
                <svg
                  className="w-3.5 h-3.5 text-text-muted"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={2}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"
                  />
                </svg>
              </button>
            ) : (
              <input
                ref={versionInputRef}
                type="text"
                value={version}
                onChange={(e) => setVersion(e.target.value)}
                onBlur={() => setEditingVersion(false)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === "Escape") {
                    setEditingVersion(false)
                  }
                }}
                placeholder="baseline"
                className="w-full px-2 py-1.5 text-sm bg-[#222222] border border-[#444444] rounded text-text-primary placeholder-text-muted focus:outline-none focus:border-accent lowercase"
              />
            )}
          </div>

          {/* Notes */}
          <div className="space-y-1.5">
            <label className="text-xs text-text-muted">notes</label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="optional"
              rows={3}
              className="w-full px-2 py-1.5 text-sm bg-[#222222] border border-[#444444] rounded text-text-primary placeholder-text-muted focus:outline-none focus:border-accent resize-none lowercase"
            />
          </div>

          {/* Submit button */}
          <button
            className="w-full flex items-center justify-center gap-1.5 py-2 rounded text-sm font-medium transition-all font-display tracking-tight text-white border border-transparent hover:border-white/30 cursor-pointer disabled:opacity-50"
            style={{
              background: "linear-gradient(135deg, rgb(38, 123, 241) 40%, rgb(21, 70, 139) 100%)",
              boxShadow:
                "rgba(255, 255, 255, 0.25) 2px 2px 8px 0px inset, rgba(0, 0, 0, 0.15) -2px -2px 7px 0px inset",
            }}
            onClick={handleSubmit}
            disabled={isSubmitting}
          >
            {isSubmitting ? (
              "adding..."
            ) : (
              <>
                <span className="text-lg leading-none">+</span>
                <span>Add to Leaderboard</span>
              </>
            )}
          </button>
        </div>
      </div>
    )
  }
)

LeaderboardPopover.displayName = "LeaderboardPopover"

const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001"

export interface RunSummary {
  runId: string
  provider: string
  benchmark: string
  judge: string
  answeringModel: string
  createdAt: string
  updatedAt: string
  status: "initializing" | "pending" | "running" | "stopping" | "completed" | "partial" | "failed"
  summary: {
    total: number
    ingested: number
    indexed: number
    searched: number
    answered: number
    evaluated: number
    indexingEpisodes?: {
      total: number
      completed: number
      failed: number
    }
  }
  accuracy: number | null
}

export interface QuestionCheckpoint {
  questionId: string
  containerTag: string
  question: string
  groundTruth: string
  questionType: string
  phases: {
    ingest: { status: string; completedSessions: string[] }
    indexing: { status: string }
    search: { status: string; results?: any[] }
    answer: { status: string; hypothesis?: string }
    evaluate: { status: string; score?: number; label?: string; explanation?: string }
  }
}

export interface RunDetail extends RunSummary {
  questions: Record<string, QuestionCheckpoint>
}

export interface Provider {
  name: string
  displayName: string
  concurrency: ConcurrencyConfig | null
}

export interface Benchmark {
  name: string
  displayName: string
  description: string
}

export interface QuestionTypeInfo {
  id: string
  alias: string
  description: string
}

export type QuestionTypeRegistry = Record<string, QuestionTypeInfo>

export interface PaginatedResponse<T> {
  questions: T[]
  questionTypes?: string[]
  questionTypeRegistry?: QuestionTypeRegistry
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

// Fetch wrapper with error handling
async function fetchApi<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options?.headers,
    },
  })

  if (!res.ok) {
    const error = await res.json().catch(() => ({ error: "Request failed" }))
    throw new Error(error.error || "Request failed")
  }

  return res.json()
}

// Runs
export async function getRuns(): Promise<RunSummary[]> {
  return fetchApi("/api/runs")
}

export async function getRun(runId: string): Promise<RunDetail> {
  return fetchApi(`/api/runs/${encodeURIComponent(runId)}`)
}

export async function getRunReport(runId: string): Promise<any> {
  return fetchApi(`/api/runs/${encodeURIComponent(runId)}/report`)
}

export async function getRunQuestions(
  runId: string,
  params?: { page?: number; limit?: number; status?: string; type?: string }
): Promise<PaginatedResponse<QuestionCheckpoint>> {
  const searchParams = new URLSearchParams()
  if (params?.page) searchParams.set("page", params.page.toString())
  if (params?.limit) searchParams.set("limit", params.limit.toString())
  if (params?.status) searchParams.set("status", params.status)
  if (params?.type) searchParams.set("type", params.type)

  const query = searchParams.toString()
  return fetchApi(`/api/runs/${encodeURIComponent(runId)}/questions${query ? `?${query}` : ""}`)
}

export async function getQuestion(
  runId: string,
  questionId: string
): Promise<QuestionCheckpoint & { searchResultsFile?: any }> {
  return fetchApi(
    `/api/runs/${encodeURIComponent(runId)}/questions/${encodeURIComponent(questionId)}`
  )
}

export async function deleteRun(runId: string): Promise<void> {
  await fetchApi(`/api/runs/${encodeURIComponent(runId)}`, { method: "DELETE" })
}

export async function stopRun(runId: string): Promise<{ message: string }> {
  return fetchApi(`/api/runs/${encodeURIComponent(runId)}/stop`, { method: "POST" })
}

export type PhaseId = "ingest" | "indexing" | "search" | "answer" | "evaluate" | "report"

export const PHASE_ORDER: PhaseId[] = [
  "ingest",
  "indexing",
  "search",
  "answer",
  "evaluate",
  "report",
]

export type SelectionMode = "full" | "sample" | "limit"
export type SampleType = "consecutive" | "random"

export interface SamplingConfig {
  mode: SelectionMode
  sampleType?: SampleType
  perCategory?: number
  limit?: number
}

export interface ConcurrencyConfig {
  default?: number
  ingest?: number
  indexing?: number
  search?: number
  answer?: number
  evaluate?: number
}

export async function startRun(params: {
  provider: string
  benchmark: string
  runId: string
  judgeModel: string
  answeringModel?: string
  limit?: number
  sampling?: SamplingConfig
  concurrency?: ConcurrencyConfig
  force?: boolean
  fromPhase?: PhaseId
  sourceRunId?: string
}): Promise<{ message: string; runId: string }> {
  return fetchApi("/api/runs/start", {
    method: "POST",
    body: JSON.stringify(params),
  })
}

export async function getCompletedRuns(): Promise<RunSummary[]> {
  const runs = await getRuns()
  return runs.filter((r) => r.status === "completed")
}

// Providers & Benchmarks
export async function getProviders(): Promise<{ providers: Provider[] }> {
  return fetchApi("/api/providers")
}

export async function getBenchmarks(): Promise<{ benchmarks: Benchmark[] }> {
  return fetchApi("/api/benchmarks")
}

export async function getBenchmarkQuestions(
  benchmark: string,
  params?: { page?: number; limit?: number; type?: string }
): Promise<
  PaginatedResponse<{
    questionId: string
    question: string
    questionType: string
    groundTruth: string
  }>
> {
  const searchParams = new URLSearchParams()
  if (params?.page) searchParams.set("page", params.page.toString())
  if (params?.limit) searchParams.set("limit", params.limit.toString())
  if (params?.type) searchParams.set("type", params.type)

  const query = searchParams.toString()
  return fetchApi(`/api/benchmarks/${benchmark}/questions${query ? `?${query}` : ""}`)
}

export async function getModels(): Promise<{
  models: { openai: any[]; anthropic: any[]; google: any[] }
}> {
  return fetchApi("/api/models")
}

// Latency stats structure
export interface LatencyStats {
  min: number
  max: number
  mean: number
  median: number
  p95: number
  p99: number
  stdDev: number
  count: number
}

export interface LatencyByPhase {
  ingest: LatencyStats
  indexing: LatencyStats
  search: LatencyStats
  answer: LatencyStats
  evaluate: LatencyStats
  total: LatencyStats
}

// Evaluation result for individual questions
export interface EvaluationResult {
  questionId: string
  questionType: string
  question?: string
  groundTruth: string
  hypothesis: string
  score: number
  label: string
  explanation: string
  searchResults?: any[]
  searchDurationMs?: number
  answerDurationMs?: number
  totalDurationMs?: number
}

// Leaderboard
export interface LeaderboardEntry {
  id: number
  runId: string
  provider: string
  benchmark: string
  version: string
  accuracy: number
  totalQuestions: number
  correctCount: number
  byQuestionType: Record<string, { total: number; correct: number; accuracy: number }>
  questionTypeRegistry: QuestionTypeRegistry | null
  latencyStats: LatencyByPhase | null
  evaluations: EvaluationResult[]
  providerCode: string
  promptsUsed: Record<string, string> | null
  judgeModel: string
  answeringModel: string
  addedAt: string
  notes: string | null
}

export async function getLeaderboard(): Promise<{ entries: LeaderboardEntry[] }> {
  return fetchApi("/api/leaderboard")
}

export async function getLeaderboardEntry(id: number): Promise<LeaderboardEntry> {
  return fetchApi(`/api/leaderboard/${id}`)
}

export async function addToLeaderboard(
  runId: string,
  options?: { notes?: string; version?: string }
): Promise<{ message: string; entry: LeaderboardEntry }> {
  return fetchApi("/api/leaderboard", {
    method: "POST",
    body: JSON.stringify({ runId, notes: options?.notes, version: options?.version }),
  })
}

export async function removeFromLeaderboard(id: number): Promise<void> {
  await fetchApi(`/api/leaderboard/${id}`, { method: "DELETE" })
}

// Downloads
export interface ActiveDownload {
  benchmark: string
  displayName: string
  runId: string
}

export interface DownloadsResponse {
  hasActive: boolean
  downloads: ActiveDownload[]
}

export async function getActiveDownloads(): Promise<DownloadsResponse> {
  return fetchApi("/api/downloads")
}

// Compares
export type CompareStatus = "pending" | "running" | "stopping" | "completed" | "failed" | "partial"

export interface CompareRunInfo {
  provider: string
  runId: string
  status: string
  accuracy: number | null
  error?: string
  progress?: {
    total: number
    ingested: number
    indexed: number
    searched: number
    answered: number
    indexingEpisodes?: {
      total: number
      completed: number
      failed: number
    }
    evaluated: number
  }
}

export interface CompareRunProgress {
  provider: string
  runId: string
  progress: {
    total: number
    ingested: number
    indexed: number
    searched: number
    answered: number
    evaluated: number
  }
  status: string
}

export interface CompareSummary {
  compareId: string
  providers: string[]
  benchmark: string
  judge: string
  answeringModel: string
  status: CompareStatus
  createdAt: string
  updatedAt: string
  accuracy: number | null
  runProgress?: CompareRunProgress[]
}

export interface CompareDetail extends CompareSummary {
  sampling?: SamplingConfig
  targetQuestionIds?: string[]
  runs: CompareRunInfo[]
}

export interface BenchmarkResult {
  runId: string
  provider: string
  benchmark: string
  version?: string
  // Fields can be at root level or nested in summary
  accuracy?: number
  totalQuestions?: number
  correctCount?: number
  summary?: {
    totalQuestions: number
    correctCount: number
    accuracy: number
  }
  byQuestionType: Record<string, { total: number; correct: number; accuracy: number }>
  questionTypeRegistry: QuestionTypeRegistry | null
