function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((t) => t.length > 1 && !STOP_WORDS.has(t))
}

// ─── BM25 Index ──────────────────────────────────────────────────────────────

const BM25_K1 = 1.2
const BM25_B = 0.75

interface BM25Index {
  /** Inverted index: term -> Map<chunkId, termFrequency> */
  invertedIndex: Map<string, Map<string, number>>
  /** Document lengths (in tokens) */
  docLengths: Map<string, number>
  /** Average document length */
  avgDocLength: number
  /** Total number of documents */
  docCount: number
}

function createBM25Index(): BM25Index {
  return {
    invertedIndex: new Map(),
    docLengths: new Map(),
    avgDocLength: 0,
    docCount: 0,
  }
}

function addToBM25Index(index: BM25Index, chunkId: string, text: string): void {
  const tokens = tokenize(text)
  index.docLengths.set(chunkId, tokens.length)
  index.docCount++

  // Update average document length
  let totalLength = 0
  for (const len of index.docLengths.values()) {
    totalLength += len
  }
  index.avgDocLength = totalLength / index.docCount

  // Build term frequency map
  const termFreqs = new Map<string, number>()
  for (const token of tokens) {
    termFreqs.set(token, (termFreqs.get(token) || 0) + 1)
  }

  // Update inverted index
  for (const [term, freq] of termFreqs) {
    if (!index.invertedIndex.has(term)) {
      index.invertedIndex.set(term, new Map())
    }
    index.invertedIndex.get(term)!.set(chunkId, freq)
  }
}

function searchBM25(index: BM25Index, query: string): Map<string, number> {
  const queryTerms = tokenize(query)
  const scores = new Map<string, number>()

  for (const term of queryTerms) {
    const postings = index.invertedIndex.get(term)
    if (!postings) continue

    const df = postings.size
    const idf = Math.log((index.docCount - df + 0.5) / (df + 0.5) + 1)

    for (const [chunkId, tf] of postings) {
      const docLength = index.docLengths.get(chunkId) || 0
      const numerator = tf * (BM25_K1 + 1)
      const denominator = tf + BM25_K1 * (1 - BM25_B + BM25_B * (docLength / index.avgDocLength))
      const termScore = idf * (numerator / denominator)

      scores.set(chunkId, (scores.get(chunkId) || 0) + termScore)
    }
  }

  return scores
}

// ─── Vector Search ───────────────────────────────────────────────────────────

function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) return 0

  let dot = 0
  let normA = 0
  let normB = 0

  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i]
    normA += a[i] * a[i]
    normB += b[i] * b[i]
  }

  const denominator = Math.sqrt(normA) * Math.sqrt(normB)
  if (denominator === 0) return 0

  return dot / denominator
}

// ─── Hybrid Search Engine ────────────────────────────────────────────────────

/** Weight for vector similarity in hybrid score */
const VECTOR_WEIGHT = 0.7
/** Weight for BM25 keyword score in hybrid score */
const BM25_WEIGHT = 0.3

export class HybridSearchEngine {
  private containers: Map<
    string,
    {
      chunks: Map<string, Chunk>
      bm25Index: BM25Index
    }
  > = new Map()

  private getContainer(containerTag: string) {
    if (!this.containers.has(containerTag)) {
      this.containers.set(containerTag, {
        chunks: new Map(),
        bm25Index: createBM25Index(),
      })
    }
    return this.containers.get(containerTag)!
  }

  addChunks(containerTag: string, chunks: Chunk[]): void {
    const container = this.getContainer(containerTag)

    for (const chunk of chunks) {
      container.chunks.set(chunk.id, chunk)
      addToBM25Index(container.bm25Index, chunk.id, chunk.content)
    }
  }

  search(containerTag: string, queryEmbedding: number[], query: string, limit: number): SearchResult[] {
    const container = this.containers.get(containerTag)
    if (!container || container.chunks.size === 0) return []

    // BM25 keyword scores
    const bm25Scores = searchBM25(container.bm25Index, query)

    // Vector similarity scores
    const vectorScores = new Map<string, number>()
    for (const [chunkId, chunk] of container.chunks) {
      const sim = cosineSimilarity(queryEmbedding, chunk.embedding)
      vectorScores.set(chunkId, sim)
    }

    // Normalize BM25 scores to 0-1 range
    let maxBM25 = 0
    for (const score of bm25Scores.values()) {
      if (score > maxBM25) maxBM25 = score
    }

    const normalizedBM25 = new Map<string, number>()
    for (const [chunkId, score] of bm25Scores) {
      normalizedBM25.set(chunkId, maxBM25 > 0 ? score / maxBM25 : 0)
    }

    // Compute hybrid scores
    const hybridScores: Array<{
      chunkId: string
      score: number
      vectorScore: number
      bm25Score: number
    }> = []

    for (const [chunkId] of container.chunks) {
      const vs = vectorScores.get(chunkId) || 0
      const bs = normalizedBM25.get(chunkId) || 0
      const hybrid = VECTOR_WEIGHT * vs + BM25_WEIGHT * bs

      hybridScores.push({
        chunkId,
        score: hybrid,
        vectorScore: vs,
        bm25Score: bs,
      })
    }

    // Sort by hybrid score descending
    hybridScores.sort((a, b) => b.score - a.score)

    // Return top results
    return hybridScores.slice(0, limit).map((result) => {
      const chunk = container.chunks.get(result.chunkId)!
      return {
        content: chunk.content,
        score: result.score,
        vectorScore: result.vectorScore,
        bm25Score: result.bm25Score,
        sessionId: chunk.sessionId,
        chunkIndex: chunk.chunkIndex,
        date: chunk.date,
        metadata: chunk.metadata,
      }
    })
  }

  clear(containerTag: string): void {
    this.containers.delete(containerTag)
  }

  getChunkCount(containerTag: string): number {
    return this.containers.get(containerTag)?.chunks.size || 0
  }
}

import { writeFileSync, mkdirSync, existsSync } from "fs"
import { join } from "path"
import type { Provider } from "../../types/provider"
import type { Benchmark } from "../../types/benchmark"
import type { RunCheckpoint } from "../../types/checkpoint"
import { CheckpointManager } from "../checkpoint"
import { logger } from "../../utils/logger"
import { ConcurrentExecutor } from "../concurrent"
import { resolveConcurrency } from "../../types/concurrency"

export async function runSearchPhase(
  provider: Provider,
  benchmark: Benchmark,
  checkpoint: RunCheckpoint,
  checkpointManager: CheckpointManager,
  questionIds?: string[]
): Promise<void> {
  const questions = benchmark.getQuestions()
  const targetQuestions = questionIds
    ? questions.filter((q) => questionIds.includes(q.questionId))
    : questions

  const pendingQuestions = targetQuestions.filter((q) => {
    const status = checkpointManager.getPhaseStatus(checkpoint, q.questionId, "search")
    const indexingStatus = checkpointManager.getPhaseStatus(checkpoint, q.questionId, "indexing")
    return status !== "completed" && indexingStatus === "completed"
  })

  if (pendingQuestions.length === 0) {
    logger.info("No questions pending search")
    return
  }

  const resultsDir = checkpointManager.getResultsDir(checkpoint.runId)
  if (!existsSync(resultsDir)) {
    mkdirSync(resultsDir, { recursive: true })
  }

  const concurrency = resolveConcurrency("search", checkpoint.concurrency, provider.concurrency)

  logger.info(`Searching ${pendingQuestions.length} questions (concurrency: ${concurrency})...`)

  await ConcurrentExecutor.execute(
    pendingQuestions,
    concurrency,
    checkpoint.runId,
    "search",
    async ({ item: question, index, total }) => {
      const containerTag = `${question.questionId}-${checkpoint.dataSourceRunId}`

      const startTime = Date.now()
      checkpointManager.updatePhase(checkpoint, question.questionId, "search", {
        status: "in_progress",
        startedAt: new Date().toISOString(),
      })

      try {
        const results = await provider.search(question.question, {
          containerTag,
          limit: 10,
          threshold: 0.3,
        })

        const durationMs = Date.now() - startTime
        const resultFile = join(resultsDir, `${question.questionId}.json`)
        const resultData = {
          questionId: question.questionId,
          question: question.question,
          questionType: question.questionType,
          groundTruth: question.groundTruth,
          containerTag,
          timestamp: new Date().toISOString(),
          durationMs,
          results,
        }

        writeFileSync(resultFile, JSON.stringify(resultData, null, 2))

        checkpointManager.updatePhase(checkpoint, question.questionId, "search", {
          status: "completed",
          resultFile,
          results,
          completedAt: new Date().toISOString(),
          durationMs,
        })

        logger.progress(index + 1, total, `Searched ${question.questionId} (${durationMs}ms)`)
        return { questionId: question.questionId, durationMs }
      } catch (e) {
        const error = e instanceof Error ? e.message : String(e)
        checkpointManager.updatePhase(checkpoint, question.questionId, "search", {
          status: "failed",
          error,
        })
        logger.error(`Failed to search ${question.questionId}: ${error}`)
        throw new Error(
          `Search failed at ${question.questionId}: ${error}. Fix the issue and resume with the same run ID.`
        )
      }
    }
  )

  logger.success("Search phase complete")
}

"use client"

interface CircularProgressProps {
  progress: number // 0 to 1
  size?: number
  strokeWidth?: number
  showPercentage?: boolean
}

export function CircularProgress({
  progress,
  size = 20,
  strokeWidth = 2.5,
  showPercentage = false,
}: CircularProgressProps) {
  const radius = (size - strokeWidth) / 2
  const circumference = 2 * Math.PI * radius
  const offset = circumference - progress * circumference

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      className="transform -rotate-90"
    >
      {/* Background circle */}
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        className="text-[#333333]"
      />

      {/* Progress circle - using the lighter blue from gradient (top-left color) */}
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="rgb(38, 123, 241)"
        strokeWidth={strokeWidth}
        strokeDasharray={circumference}
        strokeDashoffset={offset}
        strokeLinecap="round"
        className="transition-all duration-300"
      />

      {/* Optional percentage text */}
      {showPercentage && (
        <text
          x="50%"
          y="50%"
          textAnchor="middle"
          dominantBaseline="middle"
          className="fill-text-primary text-[8px] font-mono transform rotate-90"
          style={{ transformOrigin: "center" }}
        >
          {Math.round(progress * 100)}
        </text>
      )}
    </svg>
  )
}

import type { ProviderName } from "../../types/provider"
import type { BenchmarkName } from "../../types/benchmark"
import { orchestrator, CheckpointManager } from "../../orchestrator"
import { getAvailableProviders } from "../../providers"
import { getAvailableBenchmarks } from "../../benchmarks"
import { listAvailableModels } from "../../utils/models"
import { logger } from "../../utils/logger"

const DEFAULT_JUDGE_MODEL = "gpt-4o"

interface TestArgs {
  provider?: string
  benchmark?: string
  judgeModel?: string
  runId: string
  questionId: string
  answeringModel?: string
}

export function parseTestArgs(args: string[]): TestArgs | null {
  const parsed: Partial<TestArgs> = {}

  for (let i = 0; i < args.length; i++) {
    const arg = args[i]
    if (arg === "-p" || arg === "--provider") {
      parsed.provider = args[++i]
    } else if (arg === "-b" || arg === "--benchmark") {
      parsed.benchmark = args[++i]
    } else if (arg === "-j" || arg === "--judge") {
      parsed.judgeModel = args[++i]
    } else if (arg === "-r" || arg === "--run-id") {
      parsed.runId = args[++i]
    } else if (arg === "-q" || arg === "--question-id") {
      parsed.questionId = args[++i]
    } else if (arg === "-m" || arg === "--answering-model") {
      parsed.answeringModel = args[++i]
    }
  }

  // runId and questionId are always required
  if (!parsed.runId || !parsed.questionId) {
    return null
  }

  return parsed as TestArgs
}

export async function testQuestionCommand(args: string[]): Promise<void> {
  const parsed = parseTestArgs(args)

  if (!parsed) {
    console.log(
      "Usage: bun run src/index.ts test -r <runId> -q <questionId> [-j <judge-model>] [-m <model>]"
    )
    console.log("")
    console.log("Options:")
    console.log("  -r, --run-id           Run identifier (must have completed ingest phase)")
    console.log("  -q, --question-id      Question ID to test")
    console.log(`  -j, --judge            Judge model (default: ${DEFAULT_JUDGE_MODEL})`)
    console.log("  -m, --answering-model  Answering model (default: gpt-4o)")
    console.log("")
    console.log(`Available models: ${listAvailableModels().join(", ")}`)
    return
  }

  const checkpointManager = new CheckpointManager()

  if (!checkpointManager.exists(parsed.runId)) {
    logger.error(`No run found: ${parsed.runId}`)
    logger.error("Run ingest phase first before testing a question")
    return
  }

  const checkpoint = checkpointManager.load(parsed.runId)!
  parsed.provider = checkpoint.provider
  parsed.benchmark = checkpoint.benchmark
  parsed.judgeModel = parsed.judgeModel || checkpoint.judge || DEFAULT_JUDGE_MODEL
  parsed.answeringModel = parsed.answeringModel || checkpoint.answeringModel

  if (!getAvailableProviders().includes(parsed.provider as ProviderName)) {
    console.error(`Invalid provider in checkpoint: ${parsed.provider}`)
    return
  }

  if (!getAvailableBenchmarks().includes(parsed.benchmark as BenchmarkName)) {
    console.error(`Invalid benchmark in checkpoint: ${parsed.benchmark}`)
    return
  }

  await orchestrator.testQuestion({
    provider: parsed.provider as ProviderName,
    benchmark: parsed.benchmark as BenchmarkName,
    judgeModel: parsed.judgeModel,
    runId: parsed.runId,
    questionId: parsed.questionId,
    answeringModel: parsed.answeringModel,
  })
}

